-- v9_store.sql — a real schema-v9 engram store, captured before CURRENT_VERSION
-- moved to 10. After that bump the tree can no longer produce one, so this dump
-- is the only input the v9→v10 migration tests have. Regenerate it only from a
-- checkout whose CURRENT_VERSION is still 9.
--
-- Generated by:
--   ENGRAM_STORE=<tmp> ENGRAM_BENCH_FORCE_STUB=1 target/debug/engram remember … \
--     --offline --autonomy strict --facts-json …        (8 memories, 2 KBs)
--   engram facts resolve <id> --action supersede-old|reject-new|keep-both
--   sqlite3 <tmp>/db.sqlite .dump
-- plus the hand-written rows below, which the CLI cannot produce.
--
-- What is seeded, and which property each case exists for:
--   * 8 memories, 11 facts, 2 KBs (personal, work) — `admin rebuild --kb` needs
--     a second KB whose rows must come back bit-identical.
--   * one caller-resolved pair (Porto supersedes Lisbon, resolution='caller')
--     → migration verdict `close_old`, authority `caller`.
--   * one caller-rejected pair (Braga rejected in favour of Lisbon)
--     → verdict `reject_new`.
--   * one caller `keep-both` pair in the work KB → verdict `keep_both`.
--   * one fact_extraction_log row (the Portuguese-preference memory went through
--     the real extraction path) → the derivations backfill has something to find.
--   * fact cccccccc-…0001 (Faro): valid_from 2027-01-01 POST-DATES its
--     superseded_at 2026-02-01. Without the MAX() clamp the migration writes a
--     negative-length interval. Written by hand: no live v9 write path produces
--     a future-dated valid_from on a superseded row.
--   * fact cccccccc-…0002 (has_role Engineer): valid_until set, superseded_by
--     NULL — a closed interval with no successor. Only a v2 import can make one,
--     and step 2's third UPDATE exists for exactly this row.
--   * fact cccccccc-…0003 + queue row dddddddd-…0001: the SAME question
--     (ana / lives_in / {braga, porto}) re-asked by a later re-derivation, so two
--     OPEN rows share one decision_key. The duplicate-key collapse must merge
--     them before idx_fcq_open_key is created, or the migration aborts on every
--     store with a backlog. Survivor is the earlier row (created_at 22:53), the
--     hand-written one (created_at 2026-07-01) is the loser.
--   * queue rows dddddddd-…0002 (open) and dddddddd-…0003 (resolved): both
--     reference facts that no longer exist. These CANNOT be seeded through the
--     CLI — fact_conflict_queue carries ON DELETE CASCADE on both fact FKs and
--     open() sets PRAGMA foreign_keys = ON, so deleting the facts takes the queue
--     row with them. That cascade is the defect this build exists to fix; in the
--     wild the rows come from stores written before the FK landed, or repaired
--     with foreign keys off. They were inserted under PRAGMA foreign_keys=OFF,
--     which the dump's own leading pragma reproduces on load.
--
-- Load with conn.execute_batch(include_str!(...)) into a TempDir file, then call
-- SqliteStore::open on it: that triggers the real migration.
/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schema_version (
    version INTEGER PRIMARY KEY
);
INSERT INTO schema_version VALUES(9);
CREATE TABLE memories (
    id               TEXT PRIMARY KEY,
    content          TEXT NOT NULL,
    created_at       TEXT NOT NULL,
    event_time       TEXT,
    importance       INTEGER NOT NULL DEFAULT 5,
    emotional_weight INTEGER NOT NULL DEFAULT 0,
    access_count     INTEGER NOT NULL DEFAULT 0,
    last_accessed    TEXT,
    stability        REAL NOT NULL DEFAULT 1.0,
    source_json      TEXT NOT NULL,
    diary            TEXT NOT NULL DEFAULT 'default',
    valid_from       TEXT,
    valid_until      TEXT,
    tags_json        TEXT NOT NULL DEFAULT '[]',
    deleted          INTEGER NOT NULL DEFAULT 0
, kb TEXT NOT NULL DEFAULT 'default', deleted_at TEXT);
