CREATE TABLE entities (
                id              TEXT PRIMARY KEY,
                kb              TEXT NOT NULL DEFAULT 'default',
                canonical_name  TEXT NOT NULL,
                aliases_json    TEXT NOT NULL DEFAULT '[]',
                kind            TEXT NOT NULL,
                mention_count   INTEGER NOT NULL DEFAULT 0,
                UNIQUE(kb, canonical_name)
             );
CREATE TABLE knowledge_bases (
    name        TEXT PRIMARY KEY,
    description TEXT,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
INSERT INTO knowledge_bases VALUES('default','Default migrated memory and knowledge base','2026-08-01T22:53:08.386215+00:00','2026-08-01T22:53:08.386215+00:00');
INSERT INTO knowledge_bases VALUES('personal',NULL,'2026-08-01T22:53:08.393995+00:00','2026-08-01T22:53:08.453715+00:00');
INSERT INTO knowledge_bases VALUES('work',NULL,'2026-08-01T22:53:08.466604+00:00','2026-08-01T22:53:08.477923+00:00');
CREATE TABLE documents (
    id            TEXT PRIMARY KEY,
    kb            TEXT NOT NULL DEFAULT 'default',
    title         TEXT NOT NULL,
    source_path   TEXT,
    source_url    TEXT,
    doi           TEXT,
    authors_json  TEXT NOT NULL DEFAULT '[]',
    year          INTEGER,
    mode          TEXT NOT NULL DEFAULT 'general',
    created_at    TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE
);
CREATE TABLE document_sources (
    id            TEXT PRIMARY KEY,
    document_id   TEXT NOT NULL,
    kind          TEXT NOT NULL,
    uri           TEXT NOT NULL,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE
);
CREATE TABLE embedding_runs (
    id            TEXT PRIMARY KEY,
    kb            TEXT NOT NULL DEFAULT 'default',
    provider      TEXT NOT NULL,
    model         TEXT NOT NULL,
    dimensions    INTEGER NOT NULL,
    prompt_format TEXT NOT NULL,
    started_at    TEXT NOT NULL,
    finished_at   TEXT,
    chunk_count   INTEGER NOT NULL DEFAULT 0,
    status        TEXT NOT NULL DEFAULT 'running',
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE
);
CREATE TABLE source_spans (
    id           TEXT PRIMARY KEY,
    kb           TEXT NOT NULL DEFAULT 'default',
    document_id  TEXT,
    chunk_id     TEXT,
    page         INTEGER,
    section      TEXT,
    offset_start INTEGER,
    offset_end   INTEGER,
    source       TEXT,
    text_preview TEXT,
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE,
    FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE SET NULL,
    FOREIGN KEY(chunk_id) REFERENCES chunks(id) ON DELETE CASCADE
);
CREATE TABLE claims (
    id             TEXT PRIMARY KEY,
    kb             TEXT NOT NULL DEFAULT 'default',
    content        TEXT NOT NULL,
    evidence_level TEXT NOT NULL DEFAULT 'unknown',
    confidence     REAL NOT NULL DEFAULT 0.7,
    created_at     TEXT NOT NULL,
    derived_from   TEXT NOT NULL DEFAULT 'compiler',
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE
);
