CREATE TABLE IF NOT EXISTS 'claims_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'claims_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'claims_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
INSERT INTO claims_fts_config VALUES('version',4);
CREATE TABLE claim_evidence (
    claim_id       TEXT NOT NULL,
    source_span_id TEXT,
    chunk_id       TEXT,
    document_id    TEXT,
    PRIMARY KEY (claim_id, source_span_id, chunk_id),
    FOREIGN KEY(claim_id) REFERENCES claims(id) ON DELETE CASCADE,
    FOREIGN KEY(source_span_id) REFERENCES source_spans(id) ON DELETE CASCADE,
    FOREIGN KEY(chunk_id) REFERENCES chunks(id) ON DELETE CASCADE,
    FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE SET NULL
);
CREATE TABLE entity_aliases (
    id        TEXT PRIMARY KEY,
    kb        TEXT NOT NULL DEFAULT 'default',
    entity_id TEXT NOT NULL,
    alias     TEXT NOT NULL,
    alias_norm TEXT NOT NULL,
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE,
    FOREIGN KEY(entity_id) REFERENCES entities(id) ON DELETE CASCADE,
    UNIQUE(kb, alias_norm)
);
CREATE TABLE relations (
    id              TEXT PRIMARY KEY,
    kb              TEXT NOT NULL DEFAULT 'default',
    from_entity_id  TEXT NOT NULL,
    to_entity_id    TEXT NOT NULL,
    predicate       TEXT NOT NULL,
    weight          REAL NOT NULL DEFAULT 1.0,
    created_at      TEXT NOT NULL,
    provenance_json TEXT NOT NULL DEFAULT '[]',
    source_span_id  TEXT,
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE,
    FOREIGN KEY(from_entity_id) REFERENCES entities(id) ON DELETE CASCADE,
    FOREIGN KEY(to_entity_id) REFERENCES entities(id) ON DELETE CASCADE,
    FOREIGN KEY(source_span_id) REFERENCES source_spans(id) ON DELETE SET NULL,
    UNIQUE(kb, from_entity_id, to_entity_id, predicate)
);
CREATE TABLE takeaways (
    id             TEXT PRIMARY KEY,
    kb             TEXT NOT NULL DEFAULT 'default',
    document_id    TEXT,
    content        TEXT NOT NULL,
    evidence_level TEXT NOT NULL DEFAULT 'unknown',
    created_at     TEXT NOT NULL,
    citations_json TEXT NOT NULL DEFAULT '[]',
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE,
    FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE SET NULL
);
CREATE TABLE wiki_pages (
    id         TEXT PRIMARY KEY,
    kb         TEXT NOT NULL DEFAULT 'default',
    path       TEXT NOT NULL,
    title      TEXT NOT NULL,
    content    TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE,
    UNIQUE(kb, path)
);
INSERT INTO sqlite_schema(type,name,tbl_name,rootpage,sql)VALUES('table','wiki_pages_fts','wiki_pages_fts',0,'CREATE VIRTUAL TABLE wiki_pages_fts USING fts5(
    title,
    content,
    content=''wiki_pages'',
    content_rowid=''rowid'',
    tokenize=''porter unicode61''
)');
CREATE TABLE IF NOT EXISTS 'wiki_pages_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
INSERT INTO wiki_pages_fts_data VALUES(1,X'');
INSERT INTO wiki_pages_fts_data VALUES(10,X'00000000000000');
CREATE TABLE IF NOT EXISTS 'wiki_pages_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'wiki_pages_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'wiki_pages_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
INSERT INTO wiki_pages_fts_config VALUES('version',4);
CREATE TABLE compile_jobs (
    id            TEXT PRIMARY KEY,
    kb            TEXT NOT NULL DEFAULT 'default',
    status        TEXT NOT NULL DEFAULT 'queued',
    mode          TEXT NOT NULL DEFAULT 'evidence',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    message       TEXT,
    metadata_json TEXT NOT NULL DEFAULT '{}',
    FOREIGN KEY(kb) REFERENCES knowledge_bases(name) ON DELETE CASCADE
);
CREATE TABLE usage_events (
    id                       TEXT PRIMARY KEY,
    created_at               TEXT NOT NULL,
    provider                 TEXT NOT NULL,
    operation                TEXT NOT NULL,
    model                    TEXT,
    kb                       TEXT,
    diary                    TEXT,
    request_count            INTEGER NOT NULL DEFAULT 1,
    item_count               INTEGER NOT NULL DEFAULT 0,
    input_tokens_estimated   INTEGER NOT NULL DEFAULT 0,
    output_tokens_estimated  INTEGER NOT NULL DEFAULT 0,
    search_units             REAL NOT NULL DEFAULT 0,
    cost_usd_estimated       REAL NOT NULL DEFAULT 0,
    metadata_json            TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE usage_budgets (
    scope       TEXT PRIMARY KEY,
    kb          TEXT,
    daily_usd   REAL,
    monthly_usd REAL,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
CREATE TABLE fact_conflict_queue (
                 id           TEXT PRIMARY KEY,
                 new_fact_id  TEXT NOT NULL,
                 old_fact_id  TEXT NOT NULL,
                 diary        TEXT NOT NULL DEFAULT 'default',
                 kb           TEXT NOT NULL DEFAULT 'default',
                 detector     TEXT NOT NULL,
                 score        REAL,
                 suggested    TEXT,
                 note         TEXT,
                 status       TEXT NOT NULL DEFAULT 'open',
                 created_at   TEXT NOT NULL,
                 resolved_at  TEXT,
                 resolved_by  TEXT,
                 UNIQUE(new_fact_id, old_fact_id),
                 FOREIGN KEY(new_fact_id) REFERENCES facts(id) ON DELETE CASCADE,
                 FOREIGN KEY(old_fact_id) REFERENCES facts(id) ON DELETE CASCADE
             );
